import 'package:flutter/material.dart'; import 'package:shopsmart_zw/services/auth_service.dart'; import 'package:shopsmart_zw/services/supabase_service.dart'; import 'pos_screen.dart'; import 'inventory_screen.dart'; import 'stocktake_screen.dart'; import 'reports_screen.dart'; import 'customers_screen.dart'; import 'admin_dashboard_screen.dart';
class HomeScreen extends StatelessWidget { const HomeScreen({super.key}); @override Widget build(BuildContext context) { return Scaffold(appBar: AppBar(title: Text('ShopSmart ZW - ${AuthService.name} 🇿🇼')), body: Padding(padding: const EdgeInsets.all(16.0), child: GridView.count(crossAxisCount: 2, crossAxisSpacing: 16, mainAxisSpacing: 16, children: [
  _menuButton(context, Icons.point_of_sale, 'SALE', const POSScreen()), if(AuthService.isManager) _menuButton(context, Icons.inventory, 'INVENTORY', const InventoryScreen()), if(AuthService.isManager) _menuButton(context, Icons.fact_check, 'STOCK TAKE', const StockTakeScreen()), if(AuthService.isManager) _menuButton(context, Icons.bar_chart, 'REPORTS', const ReportsScreen()), if(AuthService.isManager) _menuButton(context, Icons.people, 'CUSTOMERS', const CustomersScreen()),
  if(AuthService.isManager) _menuButton(context, Icons.cloud_upload, 'BACKUP', null, onTap: () async { await SupabaseService.backupSales(); ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text("Backup Complete")));}),
  if(AuthService.isSuperAdmin) _menuButton(context, Icons.dashboard, 'ADMIN', const AdminDashboardScreen()),
])))); }
Widget _menuButton(BuildContext context, IconData icon, String label, Widget? screen, {VoidCallback? onTap}) { return ElevatedButton(style: ElevatedButton.styleFrom(padding: const EdgeInsets.all(20)), onPressed: onTap?? () => Navigator.push(context, MaterialPageRoute(builder: (_) => screen!)), child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [Icon(icon, size: 40), const SizedBox(height: 10), Text(label, style: const TextStyle(fontSize: 18))]));}
